def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = []
    temp = a
    for p in range(2, a):
        while temp % p == 0:
            if is_prime(p):
                primes.append(p)
            temp //= p

    # We need exactly 3 prime factors (with multiplicity)
    return len(primes) == 3
