import math

def closest_integer(value):
    """
    Create a function that takes a value (string) representing a number
    and returns the closest integer to it. If the number is equidistant
    from two integers, round it away from zero.

    Examples
    >>> closest_integer("10")
    10
    >>> closest_integer("15.3")
    15

    Note:
    Rounding away from zero means that if the given number is equidistant
    from two integers, the one you should return is the one that is the
    farthest from zero. For example closest_integer("14.5") should
    return 15 and closest_integer("-14.5") should return -15.
    """
    num = float(value)

    # If it's already an integer, return it
    if num == int(num):
        return int(num)

    # For rounding away from zero when equidistant:
    # Python's round() uses banker's rounding (round half to even), so we can't rely on it.
    # We need to implement our own rounding.

    floor_val = math.floor(num)
    ceil_val = math.ceil(num)

    if floor_val == ceil_val:
        return int(floor_val)

    # Check if equidistant: num - floor_val == 0.5 or ceil_val - num == 0.5
    diff_to_floor = abs(num - floor_val)
    diff_to_ceil = abs(ceil_val - num)

    if abs(diff_to_floor - 0.5) < 1e-9 and abs(diff_to_ceil - 0.5) < 1e-9:
        # Equidistant: round away from zero
        if num >= 0:
            return int(ceil_val)
        else:
            return int(floor_val)
    elif diff_to_floor < diff_to_ceil:
        return int(floor_val)
    else:
        return int(ceil_val)
