def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = [i for i in range(2, a) if is_prime(i)]

    for p1 in primes:
        if a % p1 != 0:
            continue
        rest_after_p1 = a // p1
        for p2 in primes:
            if rest_after_p1 % p2 != 0:
                continue
            rest_after_p2 = rest_after_p1 // p2
            if is_prime(rest_after_p2):
                # Check that all three are prime factors and product equals a
                if p1 * p2 * rest_after_p2 == a:
                    return True

    return False
