import math

def closest_integer(value):
    '''
    Create a function that takes a value (string) representing a number
    and returns the closest integer to it. If the number is equidistant
    from two integers, round it away from zero.

    Examples
    >>> closest_integer("10")
    10
    >>> closest_integer("15.3")
    15

    Note:
    Rounding away from zero means that if the given number is equidistant
    from two integers, the one you should return is the one that is the
    farthest from zero. For example closest_integer("14.5") should
    return 15 and closest_integer("-14.5") should return -15.
    '''
    num = float(value)

    # If already an integer, return it
    if num == int(num):
        return int(num)

    # Determine the fractional part and decide rounding
    # We want to round away from zero for .5 cases

    # Get the floor of the absolute value approach:
    # For positive numbers: if frac >= 0.5, round up (ceil), else round down (floor)
    # For negative numbers: if abs(frac) >= 0.5, round down (more negative), else round up (toward zero)

    fractional = num - int(num)

    if num > 0:
        if fractional >= 0.5:
            return math.ceil(num)
        else:
            return math.floor(num)
    else:
        # For negative numbers, fractional is <= 0 (e.g., -14.5 -> int(-14.5) = -14, frac = -0.5)
        # We want to round away from zero when equidistant
        if fractional <= -0.5:
            return math.floor(num)
        else:
            return math.ceil(num)
